                    "type": "string",
                    "enum": [
                        "fileFolderMapping"
                    ]
                },
                "source": {
                    "type": "string"
                },
                "target": {
                    "type": "string"
                }
            },
            "required": [
                "source",
                "target"
            ],
            "additionalProperties": false
        },
        "operationInstallPackage": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "installPackage"
                    ]
                },
                "value": {
                    "type": "string"
                }
            },
            "required": [
                "value"
            ],
            "additionalProperties": false
        },
        "arrayOfOperations": {
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/operationExec"
                    },
                    {
                        "$ref": "#/definitions/operationFolderFileMapping"
                    },
                    {
                        "$ref": "#/definitions/operationInstallPackage"
                    }
                ]
            }
        },
        "arrayOfExecOperationsOnly": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/operationExec"
            }
        },
        "uriProtocolHttps": {
            "type": "string",
            "pattern": "^https:\\/\\/"
        },
        "uriProtocolHttp": {
            "type": "string",
            "pattern": "^http:\\/\\/"
        },
        "httpsRedirect": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "url": {
                    "$ref": "#/definitions/uriProtocolHttps"
