                "cert": {
                    "description": "SSL certificate to apply to a http redirect 'from' URL.",
                    "type": "string"
                }
            },
            "required": [
                "url",
                "cert"
            ]
        },
        "httpRedirect": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "url": {
                    "$ref": "#/definitions/uriProtocolHttp"
                },
                "cert": {
                    "type": "null",
                    "enum": [
                        null
                    ]
                }
            },
            "required": [
                "url",
                "cert"
            ]
        }
    },
    "required": [
        "container"
    ],
    "properties": {
        "container": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "Unique per partition. Hostname of this container will this value",
                    "type": "string",
                    "pattern": "^[-_a-zA-Z0-9]+$"
                },
                "restrictTo": {
                    "description": "The version of Tredly this file is compatible with.",
                    "oneOf": [
                        {
                            "type": "string",
                            "pattern": "^(\\*|[0-9](?:\\.(\\*|[0-9]{1,}(?:\\.(\\*|[0-9]{1,}))?)?)?)$"
                        },
                        {
                            "type": "null"
                        },
                        {
                            "type": "string",
                            "maxLength": 0
                        }
                    ]
                },
                "group": {
                    "description": "Add this container to a particular group.",
                    "oneOf": [
                        {
                            "type": "string",
                            "pattern": "^[-_a-zA-Z0-9]+$"
                        },
                        {
                            "type": "null"
                        },
                        {
                            "type": "string",
                            "maxLength": 0
                        }
                    ],
                    "optional": true
                },
                "startOrder": {
                    "description": "Order in which this container is started within your container group.",
                    "type": "integer",
                    "minimum": 1,
                    "maximum": 99,
                    "default": 1
                },
                "replicate": {
                    "description": "When set to yes, this allows a container to be replicated within its container group. This is required if 'group' has been set.",
                    "type": "boolean",
                    "default": false
                },
                "buildOptions": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "publish": {
                            "description": "When set to true, on push to a Tredly host this container will be automatically validated and built.",
                            "type": "boolean",
                            "default": true
                        }
                    },
                    "required": [
                        "publish"
                    ]
                },
                "technicalOptions": {
                    "description": "These options will be set when the container is created.",
                    "type": "object",
                    "optional": true,
                    "additionalProperties": false,
                    "properties": {
                        "securelevel": {
                            "type": "integer",
                            "minimum": -1,
                            "maximum": 3
                        },
                        "devfs_ruleset": {
                            "$ref": "#/definitions/positiveInteger"
                        },
                        "enforce_statfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "children.max": {
                            "$ref": "#/definitions/positiveInteger"
                        },
                        "allow.set_hostname": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.sysvipc": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.raw_sockets": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.chflags": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.devfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.nullfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.procfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.tmpfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.zfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.quotas": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.socket_af": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "exec.prestart": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.poststart": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.prestop": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.stop": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.clean": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "exec.timeout": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "exec.fib": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "stop.timeout": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "mount.devfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "mount.fdescfs": {
                            "$ref": "#/definitions/binaryStringType"
                        }
                    }
                },
                "persistentStorage": {
                    "type": "object",
                    "optional": true,
                    "description": "Create a persistent block of storage for this container",
                    "additionalProperties": false,
                    "properties": {
                        "identifier": {
                            "description": "A unique name to identify this block of persistent storage.",
                            "type": "string",
                            "pattern": "^[-_a-zA-Z0-9]+$"
                        },
                        "mountPoint": {
                            "description": "The path within the container that the persistent storage will be mounted.",
                            "$ref": "#/definitions/stringPath"
                        }
                    },
                    "required": [
                        "identifier",
                        "mountPoint"
                    ]
                },
                "resourceLimits": {
                    "description": "Limit resources used by this container.",
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "maxCpu": {
                            "description": "The total number of cores or percent this container can utilise.",
                            "oneOf": [
                                {
                                    "type": "string",
                                    "pattern": "^[0-9]+%$"
                                },
                                {
                                    "type": "integer",
                                    "minimum": 1
                                },
                                {
                                    "$ref": "#/definitions/resourceUnlimited"
                                }
                            ],
                            "optional": true,
                            "default": "unlimited"
                        },
                        "maxHdd": {
                            "description": "The total amount of disk space, in Gigabytes (G) or Megabytes (M), this container.",
                            "oneOf": [
                                {
                                    "$ref": "#/definitions/typeSizeMegabyte"
                                },
                                {
                                    "$ref": "#/definitions/typeSizeGigabyte"
                                },
                                {
                                    "$ref": "#/definitions/resourceUnlimited"
                                }
                            ],
                            "optional": true,
                            "default": "unlimited"
                        },
                        "maxRam": {
                            "description": "The total amount of RAM, in Gigabytes (G) or Megabytes (M), this container can utilise.",
                            "oneOf": [
                                {
                                    "$ref": "#/definitions/typeSizeMegabyte"
                                },
                                {
                                    "$ref": "#/definitions/typeSizeGigabyte"
                                },
                                {
                                    "$ref": "#/definitions/resourceUnlimited"
                                }
                            ],
                            "optional": true,
                            "default": "unlimited"
                        }
                    }
                },
                "proxy": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "layer4Proxy": {
                            "description": "Layer4 proxy allows the container to use the Hosts external IP and forward traffic to your container on specific ports.",
                            "type": "boolean",
                            "default": false
                        },
                        "layer7Proxy": {
                            "description": "Group of properties for URL(s) the container services and responds to.",
                            "optional": true,
                            "type": "array",
                            "items": {
                                "type": "object",
                                "additionalProperties": false,
                                "properties": {
                                    "url": {
                                        "type": "string"
                                    },
                                    "cert": {
                                        "type": [
                                            "string",
                                            "null"
                                        ]
                                    },
                                    "enableWebsocket": {
                                        "optional": true,
                                        "type": "boolean",
                                        "default": false
                                    },
                                    "errorResponse": {
                                        "type": "boolean",
                                        "default": true
                                    },
                                    "maxFileSize": {
                                        "type": "string",
                                        "optional": true,
                                        "pattern": "^[0-9]+(m|g)$",
                                        "default": "1m"
                                    },
                                    "redirects": {
                                        "type": "array",
                                        "optional": true,
                                        "items": {
                                            "type": "object",
                                            "anyOf": [
                                                {
                                                    "$ref": "#/definitions/httpRedirect"
                                                },
                                                {
                                                    "$ref": "#/definitions/httpsRedirect"
                                                }
                                            ]
                                        }
                                    }
                                },
                                "required": [
                                    "url",
                                    "cert"
                                ]
                            }
                        }
                    },
                    "required": [
                        "layer4Proxy"
                    ]
                },
                "firewall": {
                    "type": "object",
                    "optional": true,
                    "properties": {
                        "ipv4Whitelist": {
                            "type": "array",
                            "optional": true,
                            "_uniqueItems": true,
                            "default": {},
                            "items": {
                                "$ref": "#/definitions/validIpv4WithCidr"
                            }
                        },
                        "allowPorts": {
                            "type": "object",
                            "optional": true,
                            "additionalProperties": false,
                            "_uniqueItems": true,
                            "properties": {
                                "udp": {
                                    "$ref": "#/definitions/inOutPorts"
                                },
                                "tcp": {
                                    "$ref": "#/definitions/inOutPorts"
                                }
                            }
                        }
                    }
                },
                "customDNS": {
                    "type": "array",
                    "_uniqueItems": true,
                    "optional": true,
                    "default": {},
                    "items": {
                        "$ref": "#/definitions/validIpv4"
                    }
                },
                "operations": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "onStart": {
                            "$ref": "#/definitions/arrayOfExecOperationsOnly"
                        },
                        "onStop": {
                            "$ref": "#/definitions/arrayOfExecOperationsOnly"
                        },
                        "onCreate": {
                            "$ref": "#/definitions/arrayOfOperations"
                        },
                        "onDestroy": {
                            "$ref": "#/definitions/arrayOfExecOperationsOnly"
                        }
                    }
                }
            }
        }
    }
}

{
    "title": "fabric info",
    "$schema": "http://json-schema.org/draft-06/schema#",
    "type": "object",
    "additionalProperties": false,
    "required": [
        "fabric_fq_name",
        "management_subnets",
        "loopback_subnets",
        "fabric_subnets",
        "fabric_asn_pool",
        "device_auth",
        "node_profiles"
    ],
    "properties": {
        "fabric_fq_name": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "fabric_display_name": {
            "type": "string"
        },
        "fabric_cluster_id": {
            "type": "integer"
        },
        "management_subnets": {
            "type": "array",
            "items": {
                "type": "object",
                "description": "List of the management network subnets for the fabric",
                "additionalProperties": false,
                "required": [
                    "cidr",
                    "gateway"
                ],
                "properties": {
                    "cidr": {
                        "type": "string",
                        "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
                    },
                    "gateway": {
                        "type": "string",
                        "format": "ipv4"
                    }
                }
            }
        },
        "loopback_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that fabric device loopback ips can be allocated.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "overlay_loopback_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that fabric device overlay loopback ips can be allocated.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "fabric_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that could be carved out for the p2p networks between fabric devices.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "pnf_servicechain_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that could be carved out for service chaining between fabric devices.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "fabric_asn_pool": {
            "type": "array",
            "items": {
                "title": "eBGP ASN Pool for fabric underlay network",
                "type": "object",
                "description": "List of the ASN pools that could be used to configure the eBGP peers for the IP fabric",
                "properties": {
                    "asn_min": {
                        "type": "integer"
                    },
                    "asn_max": {
                        "type": "integer"
                    }
                },
                "required": [
                    "asn_min",
                    "asn_max"
                ]
            }
        },
        "overlay_ibgp_asn": {
            "type": "integer",
            "title": "iBGP ASN for Contrail overlay network",
            "default": 64512
        },
        "device_auth": {
            "title": "Device Auth",
            "type": "object",
            "additionalProperties": false,
            "required": [
                "root_password"
            ],
            "properties": {
                "root_password": {
                    "type": "string"
                }
            }
        },
        "node_profiles": {
            "type": "array",
            "items": {
                "title": "Node profile",
                "type": "object",
                "description": "List of node profiles to be used by the fabric.",
                "additionalProperties": false,
                "properties": {
                    "node_profile_name": {
                        "type": "string"
                    },
                    "serial_nums": {
                        "type": "array",
                        "description": "Optional list of serial numbers of fabric devices that we want to associate with this node profile.",
                        "items": {
                            "type": "string"
                        }
                    }
                },
                "required": [
                    "node_profile_name"
                ]
            }
        },
        "interface_filters": {
            "type": "array",
            "items": {
                "type": "object",
                "maxProperties": 2,
                "additionalProperties": false,
                "properties": {
                    "op": {
                        "enum": [
                            "regex"
                        ]
                    },
                    "expr": {
                        "type": "string"
                    }
                },
                "title": "filter object",
                "description": "filter object having op and expr fields",
                "default": {},
                "examples": [
                    {
                        "op": "regex",
                        "expr": "^ge-"
                    },
                    {
                        "op": "regex",
                        "expr": "^xe"
                    }
                ]
            }
        },
        "import_configured": {
            "type": "boolean",
            "default": false,
            "description": "Not importing configured interfaces by default. Set this option to true if configured interfaces need to be imported as part of onboarding."
        },
        "device_count": {
            "title": "Number of fabric devices",
            "type": "integer",
            "description": "Total number of devices in the fabric that needs to be zero-touch provisioned"
        },
        "supplemental_day_0_cfg": {
            "title": "List of day 0 config that can be used to supplement the ZTP config",
            "type": "array",
            "items": {
                "type": "object",
                "required": [
                    "name",
                    "cfg"
                ],
                "properties": {
                    "name": {
                        "title": "name for the config",
                        "type": "string"
                    },
                    "cfg": {
                        "title": "config blob that contains the supplemental day-0 config",
                        "type": "string"
                    }
                }
            }
        },
        "device_to_ztp": {
            "title": "List of device serial numbers for the devices to be ZTPed",
            "type": "array",
            "items": {
                "type": "object",
                "required": [
                    "serial_number",
                    "hostname"
                ],
                "properties": {
                    "serial_number": {
                        "title": "Device serial number",
                        "type": "string"
                    },
                    "hostname": {
                        "title": "Device hostname can be optionally specified.",
                        "type": "string",
                        "pattern": "^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]*[a-zA-Z0-9])\\.)*([A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\\-]*[A-Za-z0-9])$"
                    },
                    "underlay_asn": {
                        "title": "Underlay eBGP autonomous system number",
                        "type": [
                            "integer",
                            "string"
                        ]
                    },
                    "loopback_ip": {
                        "title": "Loopback IP address",
                        "type": "string",
                        "format": "ipv4"
                    },
                    "mgmt_ip": {
                        "title": "Management IP address",
                        "type": "string",
                        "format": "ipv4"
                    },
                    "to_ztp": {
                        "title": "Include or ignore device in ZTP workflow",
                        "type": "boolean"
                    },
                    "supplemental_day_0_cfg": {
                        "title": "Name(s) of the supplemental day-0 config(s) that can be optionally specified for this device",
                        "type": [
                            "string",
                            "array"
                        ],
                        "items": {
                            "type": "string"
                        }
                    }
                }
            }
        },
        "os_version": {
            "type": "string"
        },
        "enterprise_style": {
            "type": "boolean",
            "default": true,
            "description": "True if enterprise style, false if sp-style configuration"
        },
        "disable_vlan_vn_uniqueness_check": {
            "type": "boolean",
            "default": false,
            "description": "True if vlan-vn uniqueness validation checks needs to be disabled, false if enable all complex validations"
        }
    }
}

